EP = "milgram"
TABLE = "{ tasse: 1, badge: 1, t }"
POSE_M1 = "M.handL = [-150, -560]; M.poseL = 'ouverte'; M.froncer = .4;"
PROP_MOUTON = ""
PROP_RENARD = ""
PLAQUE = "Amérique — début des années 1960"
PA = "PARTICIPANT(t, 300, { y: 760, face: 1, look: [.6, .3], froncer: .6, sourcil: .8, handR: [120, -440], poseR: 'pointe' })"
CHV = "(c2) => { dessine(c2, voix(CHERCHEUR(t, 560, { y: 760, face: -1, look: [-.6, .1], handR: [-60, -560], poseR: 'ouverte' }), ['s05a', 's09b'], t)); dessine(c2, " + PA + "); }"
X_INTRO = "(cc, t, u) => laboMilgram(cc, t, {})"
X04A = "(cc, t, u) => laboMilgram(cc, t, { derriere: (c2) => dessine(c2, CHERCHEUR(t, 560, { y: 760, face: -1, look: [-.6, 0], sourire: .4 })) })"
X04B = "(cc, t, u) => laboMilgram(cc, t, { n: Math.floor(u * 4), cri: u * .3, derriere: (c2) => { dessine(c2, CHERCHEUR(t, 560, { y: 760, face: -1, look: [-.6, 0] })); dessine(c2, " + PA + "); } })"
X05A = "(cc, t, u) => laboMilgram(cc, t, { n: 5, cri: .4, derriere: " + CHV + " })"
X05B = "(cc, t, u) => { laboMilgram(cc, t, { n: 5, eleve: 1 }); cc.save(); cc.globalAlpha = ease(seg(u, .3, .7)); F(cc, poly([[760, 200], [1060, 200], [1060, 280], [760, 280]]), GRIS.blanc, 3); cc.font = 'bold 24px Georgia'; cc.textAlign = 'center'; cc.fillStyle = GRIS.noir; cc.fillText('un acteur !', 910, 236); cc.font = 'italic 20px Georgia'; cc.fillText('décharges fausses', 910, 264); cc.restore(); }"
X06A = "(cc, t, u) => laboMilgram(cc, t, { n: 6 + Math.floor(u * 3), cri: .5 + u * .3, derriere: (c2) => { dessine(c2, CHERCHEUR(t, 560, { y: 760, face: -1, look: [-.6, 0] })); dessine(c2, PARTICIPANT(t, 300, { y: 760, face: 1, look: [.9, -.2], froncer: .8, sourcil: 1 })); } })"
X06B = "(cc, t, u) => laboMilgram(cc, t, { n: 9 + Math.floor(u * 3), cri: .9, derriere: (c2) => { dessine(c2, CHERCHEUR(t, 560, { y: 760, face: -1, look: [-.6, 0] })); const P = PARTICIPANT(t, 300, { y: 760, face: 1, look: [.6, -.5], froncer: 1, sourcil: 1, handL: [-60, -700], poseL: 'ouverte' }); P.bob += Math.sin(t * 20) * 2; dessine(c2, P); } })"
X07 = "(cc, t, u) => laboMilgram(cc, t, { n: 12, cri: 1, derriere: (c2) => { dessine(c2, CHERCHEUR(t, 560, { y: 760, face: -1, look: [-.6, 0] })); dessine(c2, voix(PARTICIPANT(t, 300, { y: 760, face: 1, look: [.6, -.4], froncer: 1, sourcil: 1, handR: [120, -440], poseR: 'pointe' }), ['s07a'], t)); } })"
X08A = "(cc, t, u) => laboMilgram(cc, t, { n: 12, cri: 1, derriere: (c2) => dessine(c2, CHERCHEUR(t, 560, { y: 760, face: -1, look: [-.6, 0], sourcil: .5, handR: [-60, -560], poseR: 'ouverte' })) })"
X08B = "(cc, t, u) => deuxSurTrois(cc, t, u)"
X09A = "(cc, t, u) => { cc.fillStyle = GRIS.clair; cc.fillRect(0, 0, W, H); cc.fillStyle = '#9a968e'; cc.fillRect(0, 640, W, H - 640); for (let k = 0; k < 5; k++) dessine(cc, PARTICIPANT(t, 140 + k * 200, { v: k, face: 1, look: [0, .2], sourire: .5 })); cc.font = 'italic bold 34px Georgia'; cc.textAlign = 'center'; cc.fillStyle = GRIS.noir; if (u > .3) cc.fillText('des gens ordinaires', 540, 110); }"
X09B = "(cc, t, u) => laboMilgram(cc, t, { n: 12, cri: .8, derriere: " + CHV + " })"
X10A = "(cc, t, u) => obeissanceChute(cc, t, u)"
X10B = "(cc, t, u) => obeissanceChute(cc, t, 1)"
X11 = "(cc, t, u) => laboMilgram(cc, t, { n: 10, cri: .6 })"
X12A = "(cc, t, u) => laboMilgram(cc, t, { n: 4, derriere: (c2) => { dessine(c2, CHERCHEUR(t, 560, { y: 760, face: -1, look: [-.6, 0], froncer: .3 })); dessine(c2, PARTICIPANT(t, 300, { y: 760, face: 1, look: [.6, -.2], handR: [140, -600], poseR: 'ouverte', sourcil: .4 })); } })"
X12B = "(cc, t, u) => { cc.fillStyle = GRIS.clair; cc.fillRect(0, 0, W, H); cc.fillStyle = '#9a968e'; cc.fillRect(0, 640, W, H - 640); dessine(cc, PARTICIPANT(t, 380, { face: 1, look: [.6, -.2], handR: [160, -620], poseR: 'ouverte' })); dessine(cc, CHERCHEUR(t, 700, { face: -1, look: [-.6, 0], sourcil: .6 })); F(cc, ell(430, 260, 110, 50), GRIS.blanc, 3); cc.font = 'bold 40px Georgia'; cc.textAlign = 'center'; cc.fillStyle = GRIS.noir; if (u > .2) cc.fillText('NON.', 430, 274); }"
X13 = "(cc, t, u) => laboMilgram(cc, t, { n: 0 })"
X14 = "(cc, t, u) => laboMilgram(cc, t, { n: 3 })"
CARNET = ["est-ce juste,", "même si", "on me le", "demande ?"]
